"use client"

import animation from "react-useanimations/lib/inbox"

import { UseAnimation, type UseAnimationProps } from "@/components/use-animation"

// "Inbox" from https://useanimations.com (MIT): https://useanimations.com/icons/inbox
export function AnimatedInbox(
  props: Omit<UseAnimationProps, "animationData">
) {
  return (
    <UseAnimation
      animationData={animation.animationData}
      interaction="hover-replay"
      {...props}
    />
  )
}

